#pragma once
inline nlohmann::json rendering116Proof(hb::gpu::Device& gpu,const std::string& fixture){using namespace hb::gpu;std::ifstream input(fixture);const auto packets=nlohmann::json::parse(input).at("rendering116");SceneRenderer r(gpu,64,64);SceneFrame f;f.clear={0,0,0,1};f.eye={0,0,1,1};f.screenEffects.emplace();auto& s=*f.screenEffects;s.eye=f.eye;s.forward={0,0,-1,0};s.inverseVP=identity;s.inverseVP[10]=-1;s.inverseVP[14]=1;s.path={1,2,1,0};s.pathQuality={1,0,0,0};s.pathEnvironment={0,0,0,65000};s.pathLens={0,10,0,0};s.transport={0,2,1,32};nlohmann::json colors,furnace;for(const auto& item:packets.items()){const auto& p=item.value();const auto data=p.at("data").get<std::vector<float>>();std::vector<std::uint8_t> bytes(data.size()*4);std::memcpy(bytes.data(),data.data(),bytes.size());auto world=r.createDataTexture(p.at("width"),p.at("height"),bytes,4,true);r.setGeometryScene(&world);s.rayPrograms=readRayPrograms(p.at("programs"));s.geometryInfo={p.at("width"),p.at("height"),p.at("nodeCount"),p.at("triangleOffset")};s.geometryLimits[2]=p.at("lightsOffset");s.geometryLimits[3]=p.at("lightCount");s.transport[0]=p.at("materialsOffset");s.pathQuality[3]=p.at("quality");s.pathLens[2]=p.at("lensMask")[0];s.pathLens[3]=p.at("lensMask")[1];s.pathOptions[1]=p.at("mediumCount");r.begin(f);const auto image=r.readPixels();colors[item.key()]={image[(32*64+32)*4],image[(32*64+32)*4+1],image[(32*64+32)*4+2]};if(item.key()=="rough"||item.key()=="closed"){auto dark=data;dark[p.at("lightsOffset").get<int>()*4+11]=0;std::memcpy(bytes.data(),dark.data(),bytes.size());r.updateRayScene(world,p.at("width"),p.at("height"),0,p.at("height"),bytes);s.pathEnvironment={1,1,1,65000};s.path={1,8,128,0};s.pathQuality[0]=4;for(int sample=0;sample<32;sample++){s.path[3]=sample*4;r.begin(f);if(sample<31)r.finish();}const auto white=r.readPixels();double mean=0;for(int y=24;y<40;y++)for(int x=24;x<40;x++){const double c=white[(y*64+x)*4]/255.0,v=c<=.04045?c/12.92:std::pow((c+.055)/1.055,2.4),aa=2.51-2.43*v,bb=.03-.59*v;mean+=(-bb+std::sqrt(bb*bb+.56*aa*v))/(2*aa*256);}assert(mean>.05&&mean<1.15);furnace[item.key()]=mean;s.pathEnvironment={0,0,0,65000};s.path={1,2,1,0};s.pathQuality[0]=1;}r.setGeometryScene(nullptr);}std::cerr<<"116 dielectric "<<colors.dump()<<std::endl;const auto red=[&](const char* name){return colors.at(name)[0].get<int>();};assert(red("rough")>20&&red("rough")>red("smooth")+15);assert(red("matched")<5);assert(red("normalLeak")<5&&red("normalFlat")<5);assert(red("closed")>10);return {{"passed",true},{"colors",colors},{"whiteEnvironment128Samples",furnace},{"roughDirectTransmission",true},{"smoothAndMatchedDeltaPreserved",true},{"geometricNormalGuard",true},{"closedMediumRadiance",true}};}
